/** 'android' in the Capacitor build, 'web' for the installable web app. */
declare const __PLATFORM__: 'web' | 'android';
/** FNV-1a of src/sim (less testing/) and src/content as 8 hex digits: Versus needs both devices' to match. */
declare const __SIM_HASH__: string;
/** The git commit the build is from (7 hex digits), or 'dev'. */
declare const __BUILD__: string;
